function a(t){if(t<128)return[t];const c=[];let r=t;for(;r>0;)c.unshift(r&127),r>>=7;for(let s=0;s<c.length-1;s++)c[s]|=128;return c}function h(t){return[t>>24&255,t>>16&255,t>>8&255,t&255]}function p(t){return[t>>8&255,t&255]}function w(t,c=120){const s=Math.round(6e7/c),o=[];o.push(...a(0),255,81,3,...h(s).slice(1));for(let f=0;f<t.length;f++){const d=t[f].map(e=>60+e);for(let e=0;e<d.length;e++)o.push(...a(0),144,d[e],100);for(let e=0;e<d.length;e++){const i=e===0?480:0;o.push(...a(i),128,d[e],0)}}o.push(...a(0),255,47,0);const u=o.length,k=[77,84,104,100,...h(6),...p(0),...p(1),...p(480),77,84,114,107,...h(u),...o];return new Blob([new Uint8Array(k)],{type:"audio/midi"})}function b(t,c,r=480){const s=Math.round(6e7/c),o=[...a(0),255,81,3,...h(s).slice(1),...a(0),255,47,0];function u(i){const m=[],T=Array.from(i.name).map(n=>n.charCodeAt(0));m.push({tick:0,data:[255,3,T.length,...T]});for(const n of i.notes){const l=i.channel-1&15;m.push({tick:n.startTick,data:[144|l,n.midiNote&127,n.velocity&127]}),m.push({tick:n.startTick+n.durationTicks,data:[128|l,n.midiNote&127,0]})}m.sort((n,l)=>n.tick-l.tick);const g=[];let B=0;for(const n of m){const l=n.tick-B;B=n.tick,g.push(...a(l),...n.data)}return g.push(...a(0),255,47,0),g}const k=t.map(u),f=1+k.length,y=[77,84,104,100,...h(6),...p(1),...p(f),...p(r)];function d(i){return[77,84,114,107,...h(i.length),...i]}const e=[...y,...d(o),...k.flatMap(d)];return new Blob([new Uint8Array(e)],{type:"audio/midi"})}function L(t,c=120,r="progression.mid"){const s=w(t,c),o=URL.createObjectURL(s),u=document.createElement("a");u.href=o,u.download=r,u.click(),URL.revokeObjectURL(o)}export{L as d,b as m};
